function formatCents(c,u="ARS"){const s=c<0?"-":"";const a=Math.abs(c);return`${s}${u} ${Math.floor(a/100)}.${String(a%100).padStart(2,"0")}`}
function sumCents(i){return i.reduce((a,x)=>a+x.cents,0)}
export function buildInvoice(c,l){const t=sumCents(l);return{customer:c,lines:l.map(x=>({description:x.description,quantity:x.quantity,cents:x.cents})),totalCents:t,totalLabel:formatCents(t)}}
export function monthlyReport(v){const m=new Map();for(const i of v){m.set(i.customer,(m.get(i.customer)??0)+i.totalCents)}const r=[];for(const[c,n]of m){r.push({customer:c,total:formatCents(n)})}return{rows:r,grandTotalCents:sumCents([...m.values()].map(n=>({cents:n})))}}
